        var mock = makeMockFs({
            'agents/js/agentDocGenerator.js': '// probe',
            'agents/sm.json': '{}',
            'agents/sm_merge.json': '{}',
            'agents/run_foo.json': '{}',
            'agents/real_agent.json': JSON.stringify({ name: 'Real', params: {} })
